/* UI, persistence and platform adapters. No external resources, no remote AI. */
(function(){'use strict';
const B=window.Biz,$=s=>document.querySelector(s),$$=s=>Array.from(document.querySelectorAll(s));
let state,db=null,storageMode='idb',view='dashboard',page=0,query={q:'',activity:'',status:'',from:'',to:'',sort:'date-desc'},lastFocus,undo=null,busy=false,toastTimer,docHtml='';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(fr,mg)=>state?.settings.lang==='mg'?mg:fr;
const money=n=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:0}).format(n)+' Ar';
const fmt=d=>d?d.split('-').reverse().join('/'):'—';
const name=(table,id)=>B.get(state,table,id)?.name||'—';
const native=()=>window.Capacitor?.isNativePlatform?.();
const bridge=()=>window.Capacitor.registerPlugin('BiznakoNative');
const menus=[['dashboard','◫','Vue d’ensemble','Topimaso'],['sales','↗','Ventes','Varotra'],['products','▤','Produits','Vokatra'],['lots','▣','Stock & lots','Tahiry sy andiany'],['deals','⌂','Immobilier & services','Trano sy tolotra'],['receivables','◷','À encaisser','Mbola horaisina'],['payments','↓','Encaissements','Vola voaray'],['expenses','↑','Dépenses','Fandaniana'],['contacts','♧','Contacts','Fifandraisana'],['reports','▥','Analyses','Fanadihadiana'],['assistant','✧','Assistant local','Mpanampy eo an-toerana'],['settings','⚙','Réglages & sauvegardes','Fikirana sy tahiry'],['audit','≡','Historique','Tantara']];
function toast(msg){$('#toast').textContent=msg;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4200);}
function error(e){console.error('[Biznako]',e?.message||e);toast(t('Erreur : ','Hadisoana: ')+(e?.message||e));}
function openDB(){return new Promise((resolve,reject)=>{if(!window.indexedDB){storageMode='local';return resolve();}let req;try{req=indexedDB.open('biznako-local',1);}catch(e){storageMode='local';return resolve();}req.onupgradeneeded=()=>{req.result.createObjectStore('data');};req.onsuccess=()=>{db=req.result;db.onversionchange=()=>db.close();resolve();};req.onerror=()=>{storageMode='local';resolve();};req.onblocked=()=>{storageMode='local';resolve();};});}
function readStore(key){if(storageMode==='local'){try{const v=localStorage.getItem('biznako:'+key);return Promise.resolve(v?JSON.parse(v):undefined);}catch(e){return Promise.reject(Error('Le navigateur bloque aussi le stockage local. Ouvrez le fichier dans Chrome ou Edge et autorisez les données de site.'));}}return new Promise((res,rej)=>{const tx=db.transaction('data','readonly'),r=tx.objectStore('data').get(key);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);});}
function writeStore(next,expected){if(storageMode==='local'){try{const old=localStorage.getItem('biznako:current');const current=old?JSON.parse(old):null;if(current&&current.revision!==expected)return Promise.reject(Error('Données modifiées dans une autre fenêtre. Rechargez avant de continuer.'));if(current)localStorage.setItem('biznako:previous',old);localStorage.setItem('biznako:current',JSON.stringify(next));return Promise.resolve();}catch(e){return Promise.reject(Error('Enregistrement local impossible. Le stockage du navigateur est bloqué ou plein ; exportez une sauvegarde si disponible.'));}}return new Promise((res,rej)=>{const tx=db.transaction('data','readwrite'),store=tx.objectStore('data');let conflict=false;const r=store.get('current');r.onsuccess=()=>{if(r.result&&r.result.revision!==expected){conflict=true;tx.abort();return;}if(r.result)store.put(r.result,'previous');store.put(next,'current');};tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(conflict?Error(t('Données modifiées dans une autre fenêtre. Rechargez avant de continuer.','Niova tao amin’ny varavarankely hafa ny angona. Avereno sokafana.')):tx.error||Error('Écriture annulée.'));});}
function writeAux(value,key){if(storageMode==='local'){try{if(value===null)localStorage.removeItem('biznako:'+key);else localStorage.setItem('biznako:'+key,JSON.stringify(value));return Promise.resolve()}catch{return Promise.reject(Error('Stockage local indisponible.'))}}return new Promise((res,rej)=>{const tx=db.transaction('data','readwrite'),store=tx.objectStore('data');if(value===null)store.delete(key);else store.put(value,key);tx.oncomplete=res;tx.onerror=()=>rej(tx.error)})}
async function persist(next,label){if(busy)throw Error(t('Enregistrement en cours.','Eo am-pitehirizana.'));busy=true;try{B.validate(next);const old=state;next.revision=old.revision+1;next.updatedAt=new Date().toISOString();if(label){next.audit.unshift({id:B.uid(),at:next.updatedAt,action:label});next.audit=next.audit.slice(0,5000);}await writeStore(next,old.revision);undo=old;state=next;render();if(!applyingCloud)queueCloudSync();}finally{busy=false;}}
async function mutate(table,row,action){await persist(B.commit(state,table,row,action));close(true);toast(t('Enregistré sur cet appareil.','Voatahiry amin’ity fitaovana ity.'));}
function go(v){view=v;page=0;query.q='';query.status='';render();window.scrollTo(0,0);}
function status(r){const st=state.statuses.find(s=>s.id===r.status);return `<span class="badge ${esc(st?.effect)}">${esc(stLabel(st))}</span>`;}
function stLabel(s){if(!s)return '';return ({draft:t('Brouillon','Drafitra'),valid:t('Validé','Voamarina'),cancel:t('Annulé','Nofoanana')})[s.id]&&['Brouillon','Validé','Annulé'].includes(s.label)?({draft:t('Brouillon','Drafitra'),valid:t('Validé','Voamarina'),cancel:t('Annulé','Nofoanana')})[s.id]:s.label;}
const btn=(label,action,extra='',cls='')=>`<button type="button" data-action="${action}" ${extra} class="${cls}">${label}</button>`;
const options=(arr,val,label='name')=>arr.map(r=>`<option value="${esc(r.id)}" ${r.id===val?'selected':''}>${esc(typeof label==='function'?label(r):r[label])}</option>`).join('');
function filterUI(full=true){return `<div class="filters no-print">${full?`<label class="search">${t('Rechercher','Hikaroka')}<input id="search" value="${esc(query.q)}" placeholder="${t('Nom, client, note…','Anarana, mpanjifa…')}"></label>`:''}<label>${t('Activité','Asa')}<select id="filter-activity"><option value="">${t('Toutes les activités','Asa rehetra')}</option>${options(state.activities,query.activity)}</select></label><label>${t('Du','Manomboka')}<input type="date" id="filter-from" value="${esc(query.from)}"></label><label>${t('Au','Hatramin’ny')}<input type="date" id="filter-to" value="${esc(query.to)}"></label>${full?`<label>${t('Statut','Sata')}<select id="filter-status"><option value="">${t('Tous','Rehetra')}</option>${options(state.statuses,query.status,stLabel)}</select></label><label>${t('Tri','Filaharana')}<select id="filter-sort">${[['date-desc',t('Plus récent','Vaovao aloha')],['date-asc',t('Plus ancien','Taloha aloha')],['name',t('Nom A → Z','Anarana A → Z')],['amount',t('Montant décroissant','Vola be aloha')]].map(([k,l])=>`<option value="${k}" ${query.sort===k?'selected':''}>${l}</option>`).join('')}</select></label>`:''}${btn(t('Effacer','Fafana'),'clearFilters')}${full?btn(t('Mémoriser','Tadidiana'),'saveFilter'):''}</div>${state.filters.length&&full?`<div class="inline no-print" style="margin-bottom:16px">${state.filters.filter(f=>f.view===view).map((f)=>btn(esc(f.name),'loadFilter',`data-id="${esc(f.id)}"`,'chip')+btn('×','deleteFilter',`data-id="${esc(f.id)}" aria-label="${t('Supprimer le filtre','Hamafa sivana')}"`,'chip')).join('')}</div>`:''}`;}
function render(){document.documentElement.lang=state.settings.lang;document.body.classList.toggle('dark',state.settings.theme==='dark');const menu=menus.find(m=>m[0]===view);$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar"><div class="brand"><span class="logo">b</span>biznako<span class="mobile-menu">${btn('×','menu')}</span></div><div class="eyebrow">${t('Votre quotidien, simplifié','Mora kokoa ny andavanandro')}</div><nav aria-label="${t('Navigation principale','Fizorana lehibe')}">${menus.map(([v,ic,fr,mg])=>`<button data-action="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${ic}</span>${t(fr,mg)}</button>`).join('')}</nav><div class="side-bottom"><span class="online-dot"></span>${t('Local • utilisable hors ligne','Eto an-toerana • tsy mila Internet')}<br>${t('Vos données restent sur cet appareil.','Eto amin’ity fitaovana ity ny angonao.')}<br>Biznako 1.0.0</div></aside><main class="main"><header class="topbar"><div class="inline">${btn('☰','menu',`aria-label="Menu"`,'mobile-menu')}<span class="context">${esc(state.settings.name)} <span class="muted"> / ${t(menu[2],menu[3])}</span></div><div class="tools">${undo?btn('↶','undo',`aria-label="${t('Annuler la dernière modification','Averina ny fanovana farany')}"`):''}<select id="language" aria-label="Langue / Fiteny"><option value="fr" ${state.settings.lang==='fr'?'selected':''}>FR</option><option value="mg" ${state.settings.lang==='mg'?'selected':''}>MG</option></select>${btn(state.settings.theme==='dark'?'☀':'☾','theme',`aria-label="${t('Changer le thème','Hanova loko')}"`)}${btn('?','guide',`aria-label="${t('Guide','Torolalana')}"`)}</div></header><div class="content">${state.settings.demo?`<div class="demo"><strong>${t('DÉMO — données fictives','DEMO — angona ohatra')}</strong>${btn(t('Passer à mes données','Ampiditra ny angonako'),'resetDemo')}</div>`:''}<div class="page-head"><div><div class="eyebrow">${t('Mon espace de gestion','Ny fitantanana ahy')}</div><h1>${t(menu[2],menu[3])}</h1><p class="sub">${subtitle()}</p></div>${B.tables.includes(view)?btn('+ '+t('Ajouter','Hanampy'),'add',`data-table="${view}"`,'primary'):''}</div>${content()}</div></main></div>`;bindFilters();}
function subtitle(){const subs={dashboard:[`Un regard clair sur vos activités. ${fmt(B.today())}`,`Topimaso mazava amin’ny asanao. ${fmt(B.today())}`],sales:['De la commande au paiement, sans perdre le fil.','Manomboka amin’ny baiko hatramin’ny fandoavana.'],lots:['Chaque production, chaque pot, chaque date.','Ny vokatra, ny tahiry ary ny daty.'],deals:['Suivez vos dossiers et la commission qui vous revient.','Araho ny raharaha sy ny tambin-karama ho anao.'],payments:['Uniquement les sommes réellement reçues.','Ny vola tena voaray ihany.'],expenses:['Les sorties de trésorerie validées sont considérées payées.','Ny fandaniana voamarina dia heverina ho efa voaloa.'],reports:['Des chiffres reliés aux documents sources.','Isa mifandray amin’ny antontan-kevitra.'],settings:['Votre application, vos préférences, vos sauvegardes.','Ny rindranasa, safidinao sy tahirinao.']};return t(...(subs[view]||['Des informations simples, toujours à portée de main.','Vaovao tsotra, mora jerena.']));}
function content(){if(view==='dashboard')return dashboard();if(view==='reports')return reports();if(view==='receivables')return receivables();if(view==='settings')return settings();if(view==='assistant')return assistant();if(view==='audit')return audit();return listView();}
function kpi(title,n,foot,target){return `<button class="card" data-action="nav" data-view="${target}" data-filter-status="${['sales','deals','expenses'].includes(target)?'valid':''}"><div class="kpi-title">${title}<span>↗</span></div><div class="kpi-number">${new Intl.NumberFormat('fr-FR').format(n)} <small>Ar</small></div><div class="kpi-foot">${foot}</div></button>`;}
function dashboard(){const m=B.metrics(state,query),alerts=stockAlerts();return `<section class="hero"><div><h2>${t('Gardez une longueur d’avance.','Mandrosoa amin’ny fahatokisana.')}</h2><p>${t('Ventes, stock et commissions. Tout est au même endroit.','Varotra, tahiry sy tambin-karama. Ao amin’ny toerana iray.')}</p></div>${btn('+ '+t('Nouvelle vente','Varotra vaovao'),'add','data-table="sales"')}<div class="orb" aria-hidden="true">↗</div></section>${filterUI(false)}<div class="grid kpis">${kpi(t('Ventes validées','Varotra voamarina'),m.revenue,t('Montant vendu sur la période','Vola nivarotana tamin’ny fe-potoana'),'sales')}${kpi(t('Commissions acquises','Tambiny azo'),m.fees,t('Votre part, dossiers validés','Anjaranao, raharaha voamarina'),'deals')}${kpi(t('Flux net de trésorerie','Fiovan’ny vola'),m.cash,t('Encaissements − dépenses payées','Vola voaray − fandaniana voaloa'),'reports')}${kpi(t('Reste à encaisser','Vola mbola horaisina'),m.pending,t('Documents de la période, à ce jour','Antontan-kevitry ny fe-potoana, hatreto'),'receivables')}</div><div class="grid two"><section class="card"><div class="panel-head"><h2>${t('Activités en perspective','Topimaso isaky ny asa')}</h2><span class="badge">${t('Ventes + commissions','Varotra + tambiny')}</span></div>${activityBars()}<p class="small muted">${t('Les montants de transaction immobilière ne sont pas du chiffre d’affaires. Seule votre commission est retenue.','Tsy vola miditra ny sandan’ny trano. Ny anjaranao amin’ny tambiny ihany no isaina.')}</p></section><section class="card"><div class="panel-head"><h2>${t('À surveiller','Tokony harahina')}</h2><span class="badge">${alerts.length}</span></div>${alerts.length?alerts.slice(0,4).map(a=>`<div class="alert-box">${esc(a)}</div>`).join(''):`<p class="muted">${t('Aucune alerte de stock.','Tsy misy fampitandremana momba ny tahiry.')}</p>`}${btn(t('Voir le stock','Hijery tahiry'),'nav','data-view="lots"')}</section></div><div class="grid two"><section class="card"><div class="panel-head"><h2>${t('Dernières ventes','Varotra farany')}</h2>${btn(t('Tout voir','Hijery rehetra'),'nav','data-view="sales"')}</div>${state.sales.length?`<div class="mini-list">${[...state.sales].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(r=>`<div class="mini-item"><div><strong>${esc(name('contacts',r.contact))}</strong><small>${fmt(r.date)} · ${status(r)}</small></div><div class="inline"><span class="amount">${money(B.total(r))}</span>${btn('↗','document',`data-table="sales" data-id="${esc(r.id)}" aria-label="${t('Ouvrir le document','Hanokatra taratasy')}"`)}</div></div>`).join('')}</div>`:emptyMessage('sales')}</section><section class="card"><h2>${t('Les bons réflexes','Fomba tsara')}</h2><div class="guide-step"><span class="step-num">1</span><div><strong>${t('Enregistrez vos encaissements','Raketo ny vola voaray')}</strong><p class="small muted">${t('Une vente validée n’est pas forcément payée.','Tsy voatery ho voaloa ny varotra voamarina.')}</p></div></div><div class="guide-step"><span class="step-num">2</span><div><strong>${t('Gardez une copie de vos données','Tehirizo ny dika mitovin’ny angona')}</strong><p class="small muted">${t('Exportez régulièrement une sauvegarde JSON.','Manaova tahiry JSON matetika.')}</p></div></div>${btn(t('Sauvegarder maintenant','Hanao tahiry izao'),'backup')}</section></div>`;}
function activityBars(){const rows=state.activities.filter(a=>!query.activity||query.activity===a.id).map(a=>{const m=B.metrics(state,{...query,activity:a.id});return {a,v:m.revenue+m.fees};});const max=Math.max(1,...rows.map(r=>r.v));return rows.map(r=>`<div class="bar-row"><span>${esc(r.a.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${r.v/max*100}%"></div></div><span class="bar-value">${money(r.v)}</span></div>`).join('');}
function stockAlerts(){const list=[];state.products.forEach(p=>{const lots=state.lots.filter(l=>l.product===p.id),usable=lots.filter(l=>(!l.expiry||l.expiry>=B.today())&&l.date<=B.today()).reduce((n,l)=>n+B.stock(state,l.id),0);if(usable<=p.threshold)list.push(`${p.name} : ${usable} ${t('disponible(s), seuil','azo amidy, fetra')} ${p.threshold}.`);});state.lots.filter(l=>l.expiry&&B.stock(state,l.id)>0&&l.expiry<=addDays(3)).forEach(l=>list.push(`${l.name} : ${t(l.expiry<B.today()?'périmé le':'expire le',l.expiry<B.today()?'lany daty ny':'ho lany daty ny')} ${fmt(l.expiry)} (${B.stock(state,l.id)}).`));return list;}
function addDays(n){const d=new Date();d.setDate(d.getDate()+n);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function emptyMessage(table){return `<div class="empty"><strong>${t('Tout commence ici.','Eto no manomboka.')}</strong><p>${t('Ajoutez votre premier élément pour commencer.','Ampidiro ny singa voalohany.')}</p>${btn('+ '+t('Ajouter','Hanampy'),'add',`data-table="${table}"`,'primary')}</div>`;}
function rowAmount(table,r){if(table==='sales')return B.total(r);if(table==='deals')return B.commission(r);return r.amount??r.price??r.cost??0;}
function rowActivity(table,r){if(table==='lots')return B.get(state,'products',r.product)?.activity;if(table==='payments')return B.get(state,r.type==='sale'?'sales':'deals',r.ref)?.activity;return r.activity;}
function filtered(table){return state[table].filter(r=>{const text=[r.name,r.note,name('contacts',r.contact),r.id,table==='lots'?name('products',r.product):'',table==='payments'?r.ref:''].join(' ').toLocaleLowerCase();return (!query.q||text.includes(query.q.toLocaleLowerCase()))&&(!query.activity||rowActivity(table,r)===query.activity||table==='contacts')&&(!query.status||r.status===query.status)&&(!query.from||!r.date||r.date>=query.from)&&(!query.to||!r.date||r.date<=query.to);}).sort((a,b)=>query.sort==='name'?(a.name||name('contacts',a.contact)).localeCompare(b.name||name('contacts',b.contact)):query.sort==='amount'?rowAmount(table,b)-rowAmount(table,a):query.sort==='date-asc'?(a.date||'').localeCompare(b.date||''):(b.date||'').localeCompare(a.date||''));}
function listColumns(table){return {sales:[t('Document / Client','Taratasy / Mpanjifa'),t('Date / Échéance','Daty / Fe-potoana'),t('Montant','Vola'),t('Reste dû','Mbola aloa'),t('Statut','Sata')],products:[t('Produit','Vokatra'),t('Activité','Asa'),t('Prix unitaire','Vidiny'),t('Stock total','Tahiry rehetra'),t('Seuil','Fetra')],lots:[t('Lot / Produit','Andiany / Vokatra'),t('Production','Famokarana'),t('Péremption','Fahataperana'),t('Reste / initial','Sisa / voalohany'),t('Coût unitaire','Sanda isanisany')],deals:[t('Dossier / Client','Raharaha / Mpanjifa'),t('Date / Échéance','Daty / Fe-potoana'),t('Votre commission','Ny tambinao'),t('Reste dû','Mbola aloa'),t('Statut','Sata')],payments:[t('Document','Taratasy'),t('Date','Daty'),t('Montant reçu','Vola voaray'),t('Mode','Fomba')],expenses:[t('Libellé','Anarana'),t('Date','Daty'),t('Montant','Vola'),t('Activité','Asa'),t('Statut','Sata')],contacts:[t('Nom','Anarana'),t('Téléphone','Finday'),t('Note','Fanamarihana')]}[table];}
function rowCells(table,r,plain=false){const st=plain?state.statuses.find(s=>s.id===r.status)?.label:status(r),label=esc(r.name),contact=esc(name('contacts',r.contact));switch(table){case'sales':return [`${esc(r.id.slice(-7).toUpperCase())}<small>${contact}</small>`,`${fmt(r.date)}<small>${fmt(r.due)}</small>`,money(B.total(r)),money(B.total(r)-B.paid(state,'sale',r.id)),st];case'deals':return [`${label}<small>${contact}</small>`,`${fmt(r.date)}<small>${fmt(r.due)}</small>`,money(B.commission(r)),money(B.commission(r)-B.paid(state,'deal',r.id)),st];case'products':return [label,esc(name('activities',r.activity)),money(r.price),String(state.lots.filter(l=>l.product===r.id).reduce((n,l)=>n+B.stock(state,l.id),0)),String(r.threshold)];case'lots':return [`${label}<small>${esc(name('products',r.product))}</small>`,fmt(r.date),`<span class="${r.expiry&&r.expiry<B.today()?'negative':''}">${fmt(r.expiry)}</span>`,`${B.stock(state,r.id)} / ${r.qty}<small>${t('Pertes','Fatiantoka')} : ${r.loss||0}</small>`,money(r.cost)];case'payments':return [esc(r.ref.slice(-7).toUpperCase()),fmt(r.date),money(r.amount),methodName(r.method)];case'expenses':return [label,fmt(r.date),money(r.amount),esc(name('activities',r.activity)),st];case'contacts':return [label,esc(r.phone),esc(r.note||'')];}}
function methodName(k){return {cash:t('Espèces','Vola mivantana'),mobile:'Mobile Money',bank:t('Banque','Banky')}[k]||k;}
function listView(){const rows=filtered(view),maxPage=Math.max(0,Math.ceil(rows.length/15)-1);page=Math.min(page,maxPage);const slice=rows.slice(page*15,page*15+15);return filterUI()+`<section class="card"><div class="panel-head"><h2>${rows.length} ${t('élément(s)','singa')}</h2><div class="inline">${btn('CSV','csv')}${btn(t('Imprimer / PDF','Hanonta / PDF'),'printList')}</div></div>${view==='lots'?`<p class="small muted">${t('Le coût des lots sert à calculer la marge. Enregistrez séparément les paiements de production dans Dépenses. Les lots périmés restent visibles et sont bloqués à la vente.','Ny sandan’ny andiany dia ampiasaina hikajiana ny tombony. Raketo ao amin’ny Fandaniana ny vola naloa tamin’ny famokarana. Tsy azo amidy ny lany daty.')}</p>`:''}${rows.length?`<div class="table-wrap"><table><thead><tr>${listColumns(view).map(c=>`<th>${c}</th>`).join('')}<th>${t('Actions','Hetsika')}</th></tr></thead><tbody>${slice.map(r=>`<tr>${rowCells(view,r).map(c=>`<td>${c}</td>`).join('')}<td><div class="row-actions">${btn('⋯','actions',`data-table="${view}" data-id="${esc(r.id)}" aria-label="${t('Actions sur cet élément','Hetsika amin’ity singa ity')}"`)}</div></td></tr>`).join('')}</tbody>${['sales','deals','expenses','payments'].includes(view)?`<tfoot><tr><td colspan="2">${t('Total filtré (tous statuts)','Fitambarany (sata rehetra)')}</td><td colspan="4">${money(rows.reduce((n,r)=>n+rowAmount(view,r),0))}</td></tr></tfoot>`:''}</table></div><div class="pagination">${btn('← '+t('Précédent','Teo aloha'),'prev',page===0?'disabled':'')}<span>${page+1} / ${maxPage+1}</span>${btn(t('Suivant','Manaraka')+' →','next',page===maxPage?'disabled':'')}</div>`:query.q||query.activity||query.status||query.from||query.to?`<div class="empty">${t('Aucun résultat pour ces filtres.','Tsy misy valiny amin’ireo sivana.')}</div>`:emptyMessage(view)}</section>`;}
function receivables(){const m=B.metrics(state,query);const rows=[...m.sales.map(r=>({r,table:'sales',type:'sale',amount:B.total(r)})),...m.deals.map(r=>({r,table:'deals',type:'deal',amount:B.commission(r)}))].map(x=>({...x,left:x.amount-B.paid(state,x.type,x.r.id)})).filter(x=>x.left>0).sort((a,b)=>(a.r.due||'9999').localeCompare(b.r.due||'9999'));return filterUI(false)+`<section class="card"><div class="panel-head"><h2>${t('Documents non soldés','Taratasy mbola tsy voaloa')}</h2><strong>${money(rows.reduce((n,x)=>n+x.left,0))}</strong></div><div class="table-wrap"><table><thead><tr><th>${t('Client / dossier','Mpanjifa / raharaha')}</th><th>${t('Échéance','Fe-potoana')}</th><th>${t('Reste','Sisa')}</th><th>${t('Actions','Hetsika')}</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.r.name||name('contacts',x.r.contact))}<small>${esc(x.r.id.slice(-7).toUpperCase())}</small></td><td class="${x.r.due&&x.r.due<B.today()?'negative':''}">${fmt(x.r.due)}</td><td>${money(x.left)}</td><td><div class="row-actions">${btn(t('Encaisser','Handray vola'),'pay',`data-table="${x.table}" data-id="${esc(x.r.id)}"`)}${btn('↗','document',`data-table="${x.table}" data-id="${esc(x.r.id)}" aria-label="${t('Ouvrir le document','Hanokatra taratasy')}"`)}</div></td></tr>`).join('')||`<tr><td colspan="4">${t('Aucun document à encaisser.','Tsy misy taratasy mbola horaisina vola.')}</td></tr>`}</tbody></table></div></section>`;}
function reports(){const m=B.metrics(state,query),months={};for(const p of m.payments){months[p.date.slice(0,7)]??={in:0,out:0};months[p.date.slice(0,7)].in+=p.amount;}for(const e of m.expenses){months[e.date.slice(0,7)]??={in:0,out:0};months[e.date.slice(0,7)].out+=e.amount;}return filterUI(false)+`<div class="grid kpis">${kpi(t('Encaissements','Vola voaray'),m.received,t('À la date du paiement','Amin’ny daty nandoavana'),'payments')}${kpi(t('Dépenses payées','Fandaniana voaloa'),m.out,t('Statut validé uniquement','Sata voamarina ihany'),'expenses')}${kpi(t('Marge brute produits','Tombony manta vokatra'),m.margin,t('Ventes − coût des unités vendues','Varotra − sandan’ny vokatra lafo'),'sales')}${kpi(t('Coût des produits vendus','Sandan’ny vokatra lafo'),m.cost,t('Coûts unitaires des lots','Sanda isanisany amin’ny andiany'),'lots')}</div><div class="grid two"><section class="card"><h2>${t('Flux mensuels','Fiovan’ny vola isam-bolana')}</h2><div class="table-wrap"><table><thead><tr><th>${t('Mois','Volana')}</th><th>${t('Entrées','Miditra')}</th><th>${t('Sorties','Mivoaka')}</th><th>Net</th></tr></thead><tbody>${Object.keys(months).sort().map(k=>`<tr><td>${k.split('-').reverse().join('/')}</td><td>${money(months[k].in)}</td><td>${money(months[k].out)}</td><td>${money(months[k].in-months[k].out)}</td></tr>`).join('')||`<tr><td colspan="4">${t('Aucun mouvement.','Tsy misy fiovana.')}</td></tr>`}</tbody></table></div></section><section class="card"><h2>${t('Contribution par activité','Anjara isaky ny asa')}</h2>${activityBars()}<p class="small muted">${t('La marge brute exclut les frais généraux. Le flux net n’est pas un solde bancaire : il ne comprend pas de solde d’ouverture.','Tsy tafiditra amin’ny tombony manta ny fandaniana ankapobeny. Tsy saldon’ny banky ny fiovan’ny vola: tsy misy saldo fanombohana.')}</p></section></div><div class="inline no-print">${btn(t('Imprimer / PDF','Hanonta / PDF'),'printReport')}${btn(t('Exporter les flux CSV','Hamoaka fiovana CSV'),'cashCSV')}</div>`;}
function settings(){return `<div class="grid settings-grid"><section class="card stack"><h2>${t('Préférences','Safidy')}</h2><form id="prefs" class="stack"><label>${t('Nom commercial','Anaran’ny orinasa')}<input name="name" required maxlength="100" value="${esc(state.settings.name)}"></label><label class="check"><input name="assistant" type="checkbox" ${state.settings.assistant?'checked':''}>${t('Activer les conseils locaux','Hampandeha torohevitra eo an-toerana')}</label><button class="primary">${t('Enregistrer','Hitahiry')}</button></form><p class="small muted">${t('Devise : Ariary (MGA), sans décimales. Dates : jj/mm/aaaa.','Vola: Ariary (MGA), tsy misy desimaly. Daty: jj/mm/aaaa.')}</p><h3>${t('Rappel Android','Fampahatsiahivana Android')}</h3><p class="small muted">${t('Un rappel local pour enregistrer vos opérations. Autorisation demandée uniquement à l’activation.','Fampahatsiahivana eo an-toerana mba handraketana ny asa. Angatahana ny alalana rehefa alefa ihany.')}</p><div class="inline">${btn(t('Me rappeler demain à 18 h','Ampahatsiahivo rahampitso amin’ny 18 ora'),'reminder',native()?'':'disabled')}${btn(t('Annuler le rappel','Hanafoana fampahatsiahivana'),'cancelReminder',native()?'':'disabled')}</div>${!native()?`<p class="small muted">${t('Disponible dans l’application Android uniquement.','Ao amin’ny rindranasa Android ihany.')}</p>`:''}</section><section class="card stack"><h2>${t('Sauvegarde & restauration','Tahiry sy famerenana')}</h2><p class="sub">${t('Les données sont d’abord enregistrées sur cet appareil, puis synchronisées automatiquement avec AppForge Cloud si vous vous connectez. Le mode hors ligne reste disponible.','Tehirizina eto aloha ny angona, avy eo ampifanarahana amin’ny AppForge Cloud raha miditra ianao. Azo ampiasaina tsy misy Internet.')}</p>${btn(t('Exporter la sauvegarde JSON','Hamoaka tahiry JSON'),'backup','', 'primary')}<label>${t('Restaurer une sauvegarde JSON (10 Mo max.)','Hamerina tahiry JSON (10 Mo farany)')}<input type="file" id="restore" accept=".json,application/json"></label>${btn(t('Récupérer la version locale précédente','Hamerina ny tahiry teo aloha'),'recover')}<p class="small muted">${t('Une copie précédente est conservée à chaque écriture. Elle reste sur ce même appareil.','Voatahiry ny dika teo aloha isaky ny fanovana. Eto amin’ity fitaovana ity ihany.')}</p>${btn(t('Charger la démonstration','Hampiditra demo'),'demo')}${btn(t('Effacer toutes les données','Hamafa ny angona rehetra'),'reset','','danger')}</section><section class="card stack"><div class="panel-head"><h2>${t('Mes activités','Ny asako')}</h2>${btn('+','add','data-table="activities" aria-label="Ajouter une activité"')}</div>${state.activities.map(a=>`<div class="mini-item"><div><strong>${esc(a.name)}</strong><small>${a.kind==='goods'?t('Produits / stock','Vokatra / tahiry'):t('Services / commissions','Tolotra / tambiny')}</small></div>${btn('⋯','actions',`data-table="activities" data-id="${esc(a.id)}"`)}</div>`).join('')}<div class="panel-head"><h3>${t('Statuts personnalisés','Sata manokana')}</h3>${btn('+','statusAdd','aria-label="Ajouter un statut"')}</div><p class="small muted">${t('Chaque statut utilise une règle : brouillon, validé ou annulé. Les règles existantes ne sont pas modifiées rétroactivement.','Ny sata tsirairay dia manaraka fitsipika: drafitra, voamarina na nofoanana.')}</p>${state.statuses.map(s=>`<div class="mini-item"><span>${esc(stLabel(s))}<small>${esc(s.effect)}</small></span>${!['draft','valid','cancel'].includes(s.id)?btn('×','statusDelete',`data-id="${esc(s.id)}" aria-label="Supprimer le statut"`):''}</div>`).join('')}</section><section class="card stack"><h2>AppForge Cloud · ${t('synchronisation & équipe','fampifanarahana sy ekipa')}</h2><span class="badge draft">${cloudToken?t('Connecté','Tafiditra'):t('Connexion facultative','Safidy ny fidirana')}</span><p>${t('Usage hors ligne sans restriction. Avec une session, la synchronisation Cloudflare est automatique au lancement en ligne, après les modifications et à la reconnexion.','Azo ampiasaina tsy misy fetra tsy misy Internet. Raha tafiditra, ampifanarahana ho azy amin’ny Cloudflare rehefa manokatra, manova na miverina ny Internet.')}</p>${btn(t('Se connecter ou gérer mon équipe','Hiditra na hitantana ny ekipako'),'cloudInfo')}<p class="small muted" role="status">${esc(syncMessage)}</p><p class="small muted">${t('L’accès Cloud stocke les données métier dans D1, sans chiffrement de bout en bout. Une session 30 jours est conservée dans IndexedDB sur cet appareil ; déconnectez-vous sur les appareils partagés. Google Drive est une sauvegarde facultative distincte.','Tehirizina ao D1 ny angona ary tsy misy chiffrement de bout en bout. Tazonina 30 andro ao IndexedDB ny session; mivoaha raha fitaovana ifampizarana. Safidy misaraka ny Google Drive.')}</p><h3>${t('Confidentialité locale','Tsiambaratelo eo an-toerana')}</h3><p class="small muted">${t('Le stockage local et les sauvegardes JSON ne sont pas chiffrés. Protégez l’accès au téléphone et partagez les sauvegardes avec prudence.','Tsy voafina ny tahiry eo an-toerana sy JSON. Arovy ny finday ary zarao amim-pitandremana ny backup.')}</p></section></div>`;}
function assistant(){if(!state.settings.assistant)return `<section class="card"><h2>${t('Assistant désactivé','Tsy mandeha ny mpanampy')}</h2>${btn(t('Ouvrir les réglages','Hanokatra fikirana'),'nav','data-view="settings"')}</section>`;const m=B.metrics(state),over=[...state.sales.map(r=>({...r,kind:'sale',value:B.total(r)})),...state.deals.map(r=>({...r,kind:'deal',value:B.commission(r)}))].filter(r=>B.effect(state,r)==='valid'&&r.due&&r.due<B.today()&&r.value>B.paid(state,r.kind,r.id));return `<section class="hero"><div><h2>${t('Des conseils fondés sur vos chiffres.','Torohevitra mifototra amin’ny isanao.')}</h2><p>${t('Moteur de règles local. Sans IA générative ni connexion Internet.','Fitsipika eo an-toerana. Tsy IA mamorona ary tsy mila Internet.')}</p></div><span class="orb">✧</span></section><div class="grid three"><section class="card"><h2>${t('Recouvrement','Fanangonana vola')}</h2><div class="kpi-number">${money(m.pending)}</div><p>${t(`${over.length} document(s) validé(s) en retard. Relancez les clients concernés.`,`${over.length} taratasy voamarina tara. Mifandraisa amin’ny mpanjifa.`)}</p>${btn(t('Voir les ventes','Hijery varotra'),'nav','data-view="sales"')}</section><section class="card"><h2>${t('Stock & fraîcheur','Tahiry sy kalitao')}</h2>${stockAlerts().map(a=>`<p class="alert-box">${esc(a)}</p>`).join('')||`<p>${t('Pas d’alerte détectée.','Tsy misy fampitandremana hita.')}</p>`}${btn(t('Vérifier les lots','Hanamarina andiany'),'nav','data-view="lots"')}</section><section class="card"><h2>${t('Rentabilité produits','Tombony amin’ny vokatra')}</h2><div class="kpi-number">${money(m.margin)}</div><p>${t('Marge brute des ventes validées. Comparez-la à vos autres frais, sans déduire une seconde fois le coût de production.','Tombony manta amin’ny varotra voamarina. Ampitahao amin’ny fandaniana hafa fa aza esorina fanindroany ny sandan’ny famokarana.')}</p>${btn(t('Voir les analyses','Hijery fanadihadiana'),'nav','data-view="reports"')}</section></div>`;}
function audit(){return `<section class="card"><div class="panel-head"><h2>${t('Journal local des actions','Tantaran’ny hetsika eo an-toerana')}</h2>${btn('CSV','auditCSV')}</div><p class="small muted">${t('Les 5 000 dernières actions sont conservées. Ce journal n’est ni certifié ni inviolable.','Ny hetsika 5 000 farany no voatahiry. Tsy voamarina ara-dalàna na tsy azo ovaina ity tantara ity.')}</p>${state.audit.slice(page*30,page*30+30).map(a=>`<div class="mini-item"><div><strong>${esc(a.action)}</strong><small>${esc(a.record||'')}</small></div><span class="small muted">${esc(new Date(a.at).toLocaleString(state.settings.lang==='fr'?'fr-FR':'fr-MG'))}</span></div>`).join('')||`<div class="empty">${t('Aucune action enregistrée.','Tsy misy hetsika voarakitra.')}</div>`}<div class="pagination">${btn('←','prev',page===0?'disabled':'')}<span>${page+1}</span>${btn('→','next',(page+1)*30>=state.audit.length?'disabled':'')}</div></section>`;}
function modal(title,html,footer=''){lastFocus=document.activeElement;$('#modal').innerHTML=`<section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn('×','close',`aria-label="${t('Fermer','Hakatona')}"`)}</div>${html}${footer?`<div class="dialog-footer">${footer}</div>`:''}</section>`;$('#modal').hidden=false;$('#app').inert=true;document.body.style.overflow='hidden';setTimeout(()=>$('#modal input, #modal select, #modal button')?.focus(),0);}
function close(force=false){if(!force&&$('#edit-form')?.dataset.dirty==='true'&&!confirm(t('Abandonner les modifications non enregistrées ?','Hiala tsy hitahiry ny fanovana ve?')))return;$('#modal').hidden=true;$('#app').inert=false;$('#modal').innerHTML='';document.body.style.overflow='';lastFocus?.focus();}
function field(label,key,value='',type='text',attrs=''){return `<label>${label}<input name="${key}" type="${type}" value="${esc(value)}" ${attrs}></label>`;}
function select(label,key,arr,value,empty=false,lab='name'){return `<label>${label}<select name="${key}">${empty?`<option value="">${t('Non renseigné','Tsy voalaza')}</option>`:''}${options(arr,value,lab)}</select></label>`;}
function edit(table,id=null,duplicate=false){let r=id?B.clone(B.get(state,table,id)):{id:B.uid()};if(!r)return;if(duplicate){r.id=B.uid();r.status='draft';r.date=B.today();}let fields='';const defaults={date:B.today(),status:'draft',activity:state.activities[0]?.id};r={...defaults,...r};const contact=()=>select(t('Client / contact','Mpanjifa / fifandraisana'),'contact',state.contacts,r.contact,true);const activity=()=>select(t('Activité','Asa'),'activity',state.activities,r.activity);const stat=()=>select(t('Statut','Sata'),'status',state.statuses,r.status,false,stLabel);const date=()=>field(t('Date','Daty'),'date',r.date,'date','required');const notes=()=>`<label class="full">${t('Note','Fanamarihana')}<textarea name="note" maxlength="3000">${esc(r.note||'')}</textarea></label>`;const amount=(label,key,value,min=0,step=1)=>field(label,key,value??0,'number',`required min="${min}" max="1000000000000" step="${step}"`);
if(table==='activities')fields=field(t('Nom','Anarana'),'name',r.name,'text','required maxlength="100"')+select(t('Type','Karazana'),'kind',[{id:'goods',name:t('Produits / stock','Vokatra / tahiry')},{id:'service',name:t('Services / commissions','Tolotra / tambiny')}],r.kind||'goods');
if(table==='contacts')fields=field(t('Nom','Anarana'),'name',r.name,'text','required maxlength="100"')+field(t('Téléphone','Finday'),'phone',r.phone||'','tel','maxlength="60"')+notes();
if(table==='products')fields=field(t('Nom du produit','Anaran’ny vokatra'),'name',r.name,'text','required maxlength="100"')+activity()+amount(t('Prix de vente / unité (Ar)','Vidiny isanisany (Ar)'),'price',r.price)+field(t('Unité (pot, pièce…)','Singa (pot, isa…)'),'unit',r.unit||'pot','text','required maxlength="30"')+amount(t('Alerte stock ≤','Fampitandremana tahiry ≤'),'threshold',r.threshold??10);
if(table==='lots'){if(!state.products.length){toast(t('Créez d’abord un produit.','Mamoròna vokatra aloha.'));return;}fields=field(t('Nom / numéro du lot','Anarana / laharan’ny andiany'),'name',r.name,'text','required maxlength="100"')+select(t('Produit','Vokatra'),'product',state.products,r.product)+date()+field(t('Date de péremption (facultative)','Daty fahataperana (tsy voatery)'),'expiry',r.expiry||'','date')+amount(t('Quantité produite / reçue','Isan’ny vokatra vita / voaray'),'qty',r.qty??1,1)+amount(t('Pertes / pots jetés (cumul)','Fatiantoka / vokatra nariana (fitambarany)'),'loss',r.loss??0)+amount(t('Coût de revient unitaire (Ar)','Sanda isanisany (Ar)'),'cost',r.cost)+`<p class="notice full">${t('Ce lot augmente le stock. Le coût sert à la marge ; saisissez le paiement de production dans Dépenses. Modifier son coût recalcule la marge historique des ventes de ce lot.','Mampitombo ny tahiry ity andiany ity. Ho an’ny tombony ny sanda; raketo ao amin’ny Fandaniana ny vola naloa. Manova ny tombony teo aloha ny fanovana sanda.')}</p>`+notes();}
if(table==='sales'){if(!state.lots.length){toast(t('Ajoutez un produit et un lot avant de vendre.','Ampidiro ny vokatra sy andiany alohan’ny hivarotana.'));return;}r.lines=r.lines||[{lot:state.lots[0].id,qty:1,price:B.get(state,'products',state.lots[0].product).price}];if(!id)r.activity=B.get(state,'products',state.lots[0].product).activity;fields=activity()+contact()+date()+field(t('Échéance du paiement','Fe-potoana handoavana'),'due',r.due||'','date')+stat()+`<div class="full"><h3>${t('Produits vendus','Vokatra amidy')}</h3><p class="small muted">${t('Choisissez le lot. La validation contrôle le stock et les dates de péremption.','Safidio ny andiany. Hamarinina ny tahiry sy ny daty fahataperana.')}</p><div id="lines">${r.lines.map(lineEditor).join('')}</div>${btn('+ '+t('Ajouter un produit','Hanampy vokatra'),'addLine')}<div id="sale-total" class="summary-total"></div></div>`+notes();}
if(table==='deals')fields=field(t('Dossier / service','Raharaha / tolotra'),'name',r.name,'text','required maxlength="150"')+activity()+contact()+date()+field(t('Échéance','Fe-potoana'),'due',r.due||'','date')+stat()+amount(t('Base de calcul (Ar)','Vola fototra (Ar)'),'base',r.base)+field(t('Commission (%)','Tambiny (%)'),'rate',r.rate??5,'number','required min="0" max="100" step="0.01"')+field(t('Votre part (%)','Anjaranao (%)'),'share',r.share??100,'number','required min="0" max="100" step="0.01"')+`<div id="commission-total" class="summary-total"></div><p class="notice full">${t('Votre commission = base × taux × votre part. Pour un service à prix fixe, utilisez le prix comme base, avec 100 % et 100 %. Seul un dossier validé compte comme acquis.','Ny tambinao = vola fototra × taha × anjaranao. Ho an’ny tolotra raikitra, ataovy fototra ny vidiny ary 100 % ireo taha roa. Ny raharaha voamarina ihany no isaina.')}</p>`+notes();
if(table==='expenses')fields=field(t('Libellé','Anarana'),'name',r.name,'text','required maxlength="150"')+activity()+date()+stat()+amount(t('Montant payé (Ar)','Vola voaloa (Ar)'),'amount',r.amount??1,1)+`<p class="notice full">${t('Validez uniquement après paiement. Un brouillon ne réduit pas la trésorerie.','Hamarino rehefa voaloa ihany. Tsy mampihena vola ny drafitra.')}</p>`+notes();
if(table==='payments'){const docs=[...state.sales.filter(x=>B.effect(state,x)==='valid').map(x=>({id:'sale:'+x.id,name:`${t('Vente','Varotra')} ${x.id.slice(-7)} · ${name('contacts',x.contact)} · ${money(B.total(x)-B.paid(state,'sale',x.id))}`})),...state.deals.filter(x=>B.effect(state,x)==='valid').map(x=>({id:'deal:'+x.id,name:`${x.name} · ${money(B.commission(x)-B.paid(state,'deal',x.id))}`}))];if(!docs.length){toast(t('Validez d’abord une vente ou un dossier.','Hamarino aloha ny varotra na raharaha.'));return;}fields=select(t('Document à régler / reste dû','Taratasy handoavana / sisa'),'document',docs,r.type+':'+r.ref)+date()+amount(t('Montant reçu (Ar)','Vola voaray (Ar)'),'amount',r.amount??1,1)+select(t('Moyen de paiement','Fomba fandoavana'),'method',['cash','mobile','bank'].map(id=>({id,name:methodName(id)})),r.method||'cash')+notes();}
modal(`${id&&!duplicate?t('Modifier','Hanova'):t('Ajouter','Hanampy')} · ${table==='activities'?t('Activité','Asa'):t(...menus.find(m=>m[0]===table).slice(2))}`,`<form id="edit-form" data-table="${table}" data-id="${esc(r.id)}"><div class="form-grid">${fields}</div><div id="form-error" role="alert"></div><div class="dialog-footer">${btn(t('Annuler','Hanafoana'),'close')}<button class="primary" type="submit">${t('Enregistrer','Hitahiry')}</button></div></form>`);updateTotals();}
function lineEditor(l){return `<div class="line-editor"><label>${t('Produit / lot','Vokatra / andiany')}<select class="line-lot">${options(state.lots,l.lot,x=>`${name('products',x.product)} · ${x.name} (${B.stock(state,x.id)})`)}</select></label><label>${t('Qté','Isa')}<input class="line-qty" type="number" min="1" step="1" required value="${l.qty}"></label><label>${t('Prix Ar','Vidiny Ar')}<input class="line-price" type="number" min="0" step="1" required value="${l.price}"></label>${btn('×','removeLine',`aria-label="${t('Supprimer cette ligne','Hamafa ity andalana ity')}"`)}</div>`;}
function lines(){return $$('.line-editor').map(e=>({lot:e.querySelector('.line-lot').value,qty:Number(e.querySelector('.line-qty').value),price:Number(e.querySelector('.line-price').value)}));}
function updateTotals(){if($('#sale-total'))$('#sale-total').textContent=money(B.total({lines:lines()}));if($('#commission-total')){const f=$('#edit-form');$('#commission-total').textContent=money(B.commission({base:+f.elements.base.value,rate:+f.elements.rate.value,share:+f.elements.share.value}));}}
async function saveForm(f){const table=f.dataset.table,values=Object.fromEntries(new FormData(f)),r={id:f.dataset.id,...values};['price','threshold','qty','loss','cost','base','rate','share','amount'].forEach(k=>{if(k in r)r[k]=Number(r[k]);});if(table==='sales')r.lines=lines();if(table==='payments'){[r.type,r.ref]=r.document.split(':');delete r.document;}try{await mutate(table,r);f.dataset.dirty='false';$('#modal').hidden=true;$('#app').inert=false;$('#modal').innerHTML='';document.body.style.overflow='';}catch(e){$('#form-error').innerHTML=`<p class="error">${esc(e.message)}</p>`;}}
function actions(table,id){const r=B.get(state,table,id);modal(t('Actions','Hetsika'),`<div class="stack">${btn(t('Modifier','Hanova'),'edit',`data-table="${table}" data-id="${esc(id)}"`)}${['sales','deals'].includes(table)?btn(t('Ouvrir / imprimer / PDF','Hanokatra / hanonta / PDF'),'document',`data-table="${table}" data-id="${esc(id)}"`)+btn(t('Dupliquer en brouillon','Hanao dika drafitra'),'duplicate',`data-table="${table}" data-id="${esc(id)}"`)+(B.effect(state,r)==='valid'?btn(t('Enregistrer un encaissement','Handrakitra vola voaray'),'pay',`data-table="${table}" data-id="${esc(id)}"`):''):''}${btn(t('Supprimer','Hamafa'),'delete',`data-table="${table}" data-id="${esc(id)}"`,'danger')}</div>`);}
function documentView(table,id){const r=B.get(state,table,id),isSale=table==='sales',amount=isSale?B.total(r):B.commission(r),paid=B.paid(state,isSale?'sale':'deal',id);docHtml=`<article class="document"><div class="report-head"><div class="eyebrow">${esc(state.settings.name)}</div><h1>${t(isSale?'Reçu de vente / relevé':'Relevé de commission',isSale?'Taratasy varotra':'Taratasy tambiny')}</h1><div class="inline"><span>N° ${esc(id.toUpperCase())}</span>${status(r)}${state.settings.demo?'<strong>DÉMO</strong>':''}</div></div><div class="grid form-grid"><p><strong>${t('Client','Mpanjifa')}</strong><br>${esc(name('contacts',r.contact))}<br>${esc(B.get(state,'contacts',r.contact)?.phone||'')}</p><p>${t('Date','Daty')} : ${fmt(r.date)}<br>${t('Échéance','Fe-potoana')} : ${fmt(r.due)}<br>${esc(name('activities',r.activity))}</p></div>${isSale?`<div class="table-wrap"><table><thead><tr><th>${t('Produit / lot','Vokatra / andiany')}</th><th>${t('Qté','Isa')}</th><th>${t('Prix','Vidiny')}</th><th>Total</th></tr></thead><tbody>${r.lines.map(l=>`<tr><td>${esc(name('products',B.get(state,'lots',l.lot).product))}<small>${esc(name('lots',l.lot))}</small></td><td>${l.qty}</td><td>${money(l.price)}</td><td>${money(l.qty*l.price)}</td></tr>`).join('')}</tbody></table></div>`:`<h2>${esc(r.name)}</h2><p>${money(r.base)} × ${r.rate} % × ${r.share} %</p>`}<div class="totals"><strong>Total : ${money(amount)}</strong><span>${t('Encaissé','Voaray')} : ${money(paid)}</span><strong>${t('Reste à encaisser','Mbola horaisina')} : ${money(amount-paid)}</strong></div><p>${esc(r.note||'')}</p><p class="small muted">${t('Document de gestion interne. Ce document ne remplace pas une facture fiscale conforme à votre régime.','Taratasy fitantanana anatiny. Tsy misolo faktiora ara-ketra mifanaraka amin’ny sata misy anao.')}</p></article>`;modal(t('Document','Taratasy'),docHtml,btn(t('Imprimer / enregistrer PDF','Hanonta / hitahiry PDF'),'printDoc','', 'primary'));}
async function download(filename,data,mime='application/json'){if(native()){await bridge().saveFile({filename,data,mime});toast(t('Fichier enregistré.','Voatahiry ny rakitra.'));return;}const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type:mime}));a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function backup(){return download(`Biznako_${B.today()}_${Date.now()}.json`,JSON.stringify(state,null,2));}
function strip(html){const el=document.createElement('div');el.innerHTML=html;return el.textContent;}
function listCSV(){const rows=filtered(view);return download(`Biznako_${view}_${B.today()}.csv`,B.csv([listColumns(view),...rows.map(r=>rowCells(view,r,true).map(strip))]),'text/csv;charset=utf-8');}
async function print(html){if(native())await bridge().printDocument({html:'<!doctype html><html><head><meta charset="utf-8"><style>body{font:14px sans-serif;padding:24px}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #ccc;padding:10px;text-align:left}small{display:block}button{display:none}.totals{text-align:right;display:grid;gap:10px}h1{color:#17624f}</style><\/head><body>'+html+'<\/body><\/html>'});else window.print();}
function guide(){modal(t('Bienvenue dans Biznako','Tongasoa eto amin’ny Biznako'),`<p>${t('Quelques étapes suffisent pour commencer. Vos données restent sur cet appareil.','Dingana vitsivitsy dia afaka manomboka ianao. Eto amin’ity fitaovana ity ny angonao.')}</p>${[[t('Préparez vos produits','Omano ny vokatra'),t('Produits → ajoutez le yaourt et son prix. Stock & lots → ajoutez la quantité produite, son coût et sa péremption.','Vokatra → ampidiro ny yaourt sy ny vidiny. Tahiry → ampidiro ny isa, ny sanda ary ny daty fahataperana.')],[t('Saisissez une vente','Raketo ny varotra'),t('Ajoutez un client, puis une vente avec un ou plusieurs produits. Passez au statut Validé après contrôle.','Ampidiro ny mpanjifa, avy eo ny varotra misy vokatra iray na maromaro. Ataovy Voamarina rehefa voazaha.')],[t('Enregistrez l’argent reçu','Raketo ny vola voaray'),t('Encaissements → sélectionnez la vente ou la commission validée. Vous pouvez recevoir plusieurs paiements partiels.','Vola voaray → safidio ny varotra na tambiny voamarina. Azo aloa tsikelikely.')],[t('Suivez vos commissions','Araho ny tambinao'),t('Immobilier & services → montant de base, taux de commission, votre part. Validez lorsque le droit à commission est acquis.','Trano sy tolotra → vola fototra, taha ary anjaranao. Hamarino rehefa azo antoka ny zo hahazo tambiny.')],[t('Sauvegardez régulièrement','Manaova tahiry matetika'),t('Réglages → exporter JSON. Conservez ce fichier ailleurs. La suppression des données du navigateur efface la base locale.','Fikirana → hamoaka JSON. Tehirizo any an-kafa ilay rakitra. Ho very ny tahiry raha fafana ny angon’ny navigateur.')],[t('Synchronisez entre appareils (facultatif)','Ampifanaraho amin’ny fitaovana hafa (safidy)'),t('Réglages → AppForge Cloud : l’adresse du service est intégrée automatiquement. Connectez-vous avec votre e-mail et mot de passe ou acceptez l’invitation reçue. Les modifications se synchronisent quand Internet revient. Au premier raccordement, choisissez la copie à garder. En cas de conflit sur un même élément, choisissez la version locale ou Cloud. Sans connexion ou compte, Biznako continue de fonctionner sur cet appareil.','Fikirana → AppForge Cloud: tafiditra ho azy ny adiresin’ny serivisy. Midira amin’ny e-mail sy tenimiafina na ekeo ny fanasana. Ampifanarahana rehefa miverina ny Internet. Amin’ny voalohany dia mifidiana ny tahiry hotazonina. Raha misy fifanoherana dia mifidiana ny eo an-toerana na Cloud. Mbola mandeha eto amin’ny fitaovana ny Biznako na tsy misy kaonty.')]].map(([title,body],i)=>`<div class="guide-step"><span class="step-num">${i+1}</span><div><strong>${title}</strong><p class="small muted">${body}</p></div></div>`).join('')}`,btn(t('Essayer la démo','Hanandrana demo'),'demo')+btn(t('Commencer avec mes données','Hanomboka amin’ny angonako'),'start','','primary'));}
function bindFilters(){for(const key of ['activity','status','from','to','sort']){const el=$('#filter-'+key);if(el)el.onchange=()=>{query[key]=el.value;if(query.from&&query.to&&query.from>query.to){toast(t('La date de fin doit suivre la date de début.','Tsy maintsy aorian’ny fiandohana ny farany.'));query[key]='';}page=0;render();};}if($('#search'))$('#search').oninput=e=>{const pos=e.target.selectionStart;query.q=e.target.value;page=0;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);};$('#language').onchange=async e=>{const n=B.clone(state);n.settings.lang=e.target.value;try{await persist(n);}catch(err){error(err);}};if($('#restore'))$('#restore').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error(t('Fichier trop volumineux.','Lehibe loatra ny rakitra.'));const n=B.restore(await file.text());if(confirm(t('Remplacer les données locales par cette sauvegarde ? La version précédente restera récupérable.','Hosoloina amin’ity tahiry ity ny angona? Mbola azo averina ny teo aloha.'))){await persist(n,t('Restauration JSON','Famerenana JSON'));toast(t('Sauvegarde restaurée.','Tafaverina ny tahiry.'));}}catch(err){error(err);}finally{if($('#restore'))$('#restore').value='';}};if($('#prefs'))$('#prefs').onsubmit=async e=>{e.preventDefault();try{const n=B.clone(state);n.settings.name=e.target.elements.name.value.trim();n.settings.assistant=e.target.elements.assistant.checked;await persist(n,t('Préférences modifiées','Niova ny safidy'));toast(t('Préférences enregistrées.','Voatahiry ny safidy.'));}catch(err){error(err);}};}
document.addEventListener('submit',e=>{if(e.target.id==='edit-form'){e.preventDefault();saveForm(e.target);}});
document.addEventListener('input',e=>{if(e.target.closest('#edit-form')){$('#edit-form').dataset.dirty='true';updateTotals();}});
document.addEventListener('change',e=>{if(e.target.classList.contains('line-lot')){const lot=B.get(state,'lots',e.target.value);e.target.closest('.line-editor').querySelector('.line-price').value=B.get(state,'products',lot.product).price;updateTotals();}if(e.target.closest('#edit-form'))$('#edit-form').dataset.dirty='true';});
let cloudToken='',cloudUser=null,cloudOrganizations=[],syncTimer=0,syncBusy=false,applyingCloud=false,syncMessage='En attente de connexion.';
// URL intégrée au build : les clients n’ont pas à connaître ni configurer l’endpoint.
const APPFORGE_CLOUD_API='https://appforge-cloud-api.appforge-licences-mg.workers.dev';
const cloudBase=()=>APPFORGE_CLOUD_API;
const cloudHeaders=()=>({'Authorization':'Bearer '+cloudToken,'Content-Type':'application/json'});
async function cloudRequest(path,options={}){const base=cloudBase();if(!/^https:\/\//i.test(base))throw Error(t('Adresse AppForge Cloud intégrée invalide. Vérifiez la version installée.','Diso ny adiresy Cloud tafiditra. Jereo ny kinova napetraka.'));const r=await fetch(base+path,{signal:AbortSignal.timeout(12000),...options,headers:{...cloudHeaders(),...(options.headers||{})}});const data=await r.json().catch(()=>({}));if(!r.ok){const err=Error(data.error||`Erreur Cloud ${r.status}.`);err.status=r.status;throw err}return data;}
function openCloudModal(message=''){const org=state?.settings?.cloudOrganization||'';modal(t('AppForge Cloud · équipe et synchronisation','AppForge Cloud · ekipa sy fampifanarahana'),`<div class="stack"><p>${t('L’adresse du service Cloud est déjà intégrée à Biznako : aucune configuration technique à saisir. Vos données restent d’abord sur cet appareil. Connectez-vous avec votre compte AppForge Cloud ou utilisez le code d’invitation reçu; la synchronisation démarre ensuite automatiquement. Aucun compte Google n’est requis.','Efa tafiditra ao amin’ny Biznako ny adiresin’ny Cloud: tsy mila manamboatra zavatra ara-teknika ianao. Eto amin’ity fitaovana ity aloha ny angona. Midira amin’ny kaonty AppForge Cloud na ampiasao ny kaody fanasana; mandeha ho azy avy eo ny fampifanarahana. Tsy ilaina ny Google.')}</p><div class="grid two"><section class="card"><h3>${t('Connexion','Fidirana')}</h3><form id="cloudLogin" class="stack"><label>E-mail<input name="email" type="email" autocomplete="username" required maxlength="254"></label><label>${t('Mot de passe','Tenimiafina')}<input name="password" type="password" autocomplete="current-password" required minlength="12" maxlength="128"></label><button class="primary">${t('Se connecter','Hiditra')}</button></form><hr><h3>${t('Créer un compte sur invitation','Hamorona kaonty amin’ny fanasana')}</h3><form id="cloudRegister" class="stack"><label>${t('Code d’invitation','Kaody fanasana')}<input name="inviteToken" autocomplete="off" required></label><label>E-mail<input name="email" type="email" autocomplete="email" required maxlength="254"></label><label>${t('Nom','Anarana')}<input name="name" autocomplete="name" required maxlength="120"></label><label>${t('Mot de passe (12 caractères minimum)','Tenimiafina (litera 12 farafahakeliny)')}<input name="password" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><button>${t('Créer le compte et rejoindre','Hamorona kaonty sy hiditra')}</button></form><div class="stack"><label>${t('Code reçu pour rejoindre une autre organisation','Kaody hiditra fikambanana hafa')}<input id="cloudAcceptToken" autocomplete="off"></label><button type="button" data-action="cloudAcceptInvite">${t('Accepter l’invitation','Hanaiky fanasana')}</button></div>${cloudToken?`<p>${esc(cloudUser?.name||'')} · ${esc(cloudUser?.email||'')} <button type="button" data-action="cloudSignout">${t('Se déconnecter','Hivoaka')}</button></p>`:''}<p class="small muted" role="status">${esc(message|| (cloudUser?`${cloudUser.name} · ${cloudUser.email}`:t('Hors ligne : les données locales restent disponibles.','Tsy misy Internet: mbola azo ampiasaina ny angona eo an-toerana.')))}</p></section><section class="card"><h3>${t('Organisation et membres','Fikambanana sy mpikambana')}</h3><label>${t('Organisation active','Fikambanana ampiasaina')}<select id="cloudOrg"><option value="">${t('Choisir une organisation','Misafidiana fikambanana')}</option>${cloudOrganizations.map(o=>`<option value="${esc(o.id)}" ${o.id===org?'selected':''}>${esc(o.name)} · ${esc(o.role)}</option>`).join('')}</select></label><div class="inline"><button type="button" data-action="cloudLoadOrgs">${t('Actualiser mes organisations','Havaozy ny fikambanako')}</button><label>${t('Créer une organisation','Hamorona fikambanana')}<input id="cloudOrgName" maxlength="100" placeholder="Entreprise / équipe"></label><button type="button" data-action="cloudCreateOrg">${t('Créer','Hamorona')}</button></div><label>${t('Inviter un membre par e-mail','Manasa mpikambana amin’ny e-mail')}<input id="cloudInviteEmail" type="email" maxlength="254"></label><label>${t('Rôle','Andraikitra')}<select id="cloudInviteRole"><option value="editor">Éditeur</option><option value="viewer">Lecteur</option><option value="admin">Administrateur</option></select></label><button type="button" data-action="cloudInvite">${t('Créer le code d’invitation','Hamorona kaody fanasana')}</button><textarea id="cloudInviteResult" readonly placeholder="${t('Le code à partager apparaîtra ici.','Hiseho eto ny kaody zaraina.')}"></textarea><div id="cloudMembers" class="small muted"></div></section></div><section class="card"><h3>${t('Synchronisation automatique','Fampifanarahana mandeha ho azy')}</h3><p>${t('Le premier raccordement demande de choisir entre la copie locale et celle du Cloud. Ensuite, seules les modifications compatibles sont fusionnées automatiquement. Une modification concurrente du même élément est signalée, sans écrasement silencieux.','Amin’ny fampifandraisana voalohany dia misafidy ny angona eo an-toerana na Cloud ianao. Aorian’izay dia atambatra ho azy ny fanovana tsy mifanohitra. Raha novaina miaraka ilay singa iray dia aseho ny fifanoherana fa tsy soloina mangina.')}</p><p id="cloudSyncStatus" class="small muted" role="status">${esc(message||t('État : en attente de connexion.','Sata: miandry fifandraisana.'))}</p><button type="button" data-action="cloudSyncNow">${t('Synchroniser maintenant','Hampifanaraka izao')}</button></section><p class="small muted">${t('Le fichier ouvert directement en file:// reste utilisable hors ligne, mais ne peut pas joindre le Worker. Les données Cloud sont conservées dans D1 sans chiffrement de bout en bout. Google Drive reste une sauvegarde facultative séparée.','Azo ampiasaina tsy misy Internet ny file:// fa tsy afaka mifandray amin’ny Worker. Tsy misy chiffrement de bout en bout ny angona ao D1. Safidy misaraka ny backup Google Drive.')}</p></div>`);}
async function cloudSignin(form){try{if(!navigator.onLine)throw Error(t('Connexion Internet requise pour ouvrir une session. Les données locales restent accessibles.','Ilaina ny Internet raha hiditra. Mbola azo ampiasaina ny angona eo an-toerana.'));const fd=new FormData(form),d=await cloudRequest('/v1/auth/login',{method:'POST',body:JSON.stringify({email:fd.get('email'),password:fd.get('password')})});cloudToken=d.token;cloudUser=d.user;cloudOrganizations=d.organizations||[];await writeAux({token:cloudToken},'cloud-session');form.elements.password.value='';if(!cloudOrganizations.some(o=>o.id===state.settings.cloudOrganization)&&cloudOrganizations[0]){const n=B.clone(state);n.settings.cloudOrganization=cloudOrganizations[0].id;applyingCloud=true;await persist(n,t('Organisation AppForge Cloud sélectionnée','Voafidy ny fikambanana AppForge Cloud'));applyingCloud=false;}close(true);toast(t('Connexion réussie. Synchronisation automatique activée.','Tafiditra. Mandeha ho azy ny fampifanarahana.'));queueCloudSync(100);}catch(err){error(err)}}
async function cloudRegister(form){try{const fd=new FormData(form),d=await cloudRequest('/v1/auth/register',{method:'POST',body:JSON.stringify({inviteToken:fd.get('inviteToken').trim(),email:fd.get('email'),name:fd.get('name'),password:fd.get('password')})});cloudToken=d.token;cloudUser=d.user;cloudOrganizations=d.organizations||[];await writeAux({token:cloudToken},'cloud-session');form.reset();if(cloudOrganizations[0]){const n=B.clone(state);n.settings.cloudOrganization=cloudOrganizations[0].id;applyingCloud=true;await persist(n);applyingCloud=false;}close(true);toast(t('Compte créé et invitation acceptée. Synchronisation démarrée.','Vita ny kaonty sy fanasana. Nanomboka ny fampifanarahana.'));queueCloudSync(100);}catch(err){applyingCloud=false;error(err)}}
async function cloudLoadOrganizations(){try{if(!cloudToken)throw Error(t('Connectez-vous d’abord.','Midira aloha.'));const d=await cloudRequest('/v1/organizations');cloudOrganizations=d.items||[];if(!cloudOrganizations.some(o=>o.id===state.settings.cloudOrganization)&&cloudOrganizations[0]){const n=B.clone(state);n.settings.cloudOrganization=cloudOrganizations[0].id;applyingCloud=true;await persist(n);applyingCloud=false;}openCloudModal(t(`${cloudOrganizations.length} organisation(s) chargée(s).`,'Voaray ny fikambanana.'));const org=cloudOrgId();if(org){await cloudLoadMembers(org);queueCloudSync(100)}}catch(err){error(err)}}
async function cloudLoadMembers(org){try{if(!org||!cloudToken)return;const d=await cloudRequest(`/v1/organizations/${encodeURIComponent(org)}/members`);const box=$('#cloudMembers');if(box)box.innerHTML='<h3>'+t('Membres de l’organisation','Mpikambana ao amin’ny fikambanana')+'</h3>'+((d.items||[]).map(m=>`<div class="mini-item"><span><strong>${esc(m.name)}</strong><small>${esc(m.email)}</small></span><span class="badge">${esc(m.role)} · ${esc(m.status)}</span></div>`).join('')||'<p>'+t('Aucun membre.','Tsy misy mpikambana.')+'</p>')}catch(err){const box=$('#cloudMembers');if(box)box.textContent=err.message}}
async function cloudCreateOrganization(){try{if(!cloudToken)throw Error(t('Connectez-vous d’abord.','Midira aloha.'));const name=$('#cloudOrgName')?.value.trim();if(!name)throw Error(t('Saisissez le nom de l’organisation.','Ampidiro ny anaran’ny fikambanana.'));await cloudRequest('/v1/organizations',{method:'POST',body:JSON.stringify({name})});await cloudLoadOrganizations();}catch(err){error(err)}}
async function cloudInvite(){try{const org=$('#cloudOrg')?.value,email=$('#cloudInviteEmail')?.value.trim(),role=$('#cloudInviteRole')?.value;if(!org||!email)throw Error(t('Choisissez une organisation et saisissez l’e-mail du membre.','Misafidiana fikambanana ary ampidiro ny e-mail.'));const d=await cloudRequest(`/v1/organizations/${encodeURIComponent(org)}/invitations`,{method:'POST',body:JSON.stringify({email,role})});$('#cloudInviteResult').value=d.token;syncStatus(t('Invitation créée. Transmettez le code au membre ; aucun e-mail automatique n’est envoyé.','Vita ny fanasana. Alefaso amin’ilay olona ny kaody; tsy misy mailaka alefa ho azy.'));}catch(err){error(err)}}
async function cloudAcceptInvite(){try{const token=$('#cloudAcceptToken')?.value.trim();if(!token)throw Error(t('Saisissez le code d’invitation.','Ampidiro ny kaody fanasana.'));await cloudRequest('/v1/invitations/accept',{method:'POST',body:JSON.stringify({token})});await cloudLoadOrganizations();}catch(err){error(err)}}
function cloudOrgId(){return $('#cloudOrg')?.value||state?.settings?.cloudOrganization||''}
const SYNC_TABLES=['activities','statuses','contacts','products','lots','sales','deals','payments','expenses'];
function syncSnapshot(source){const s=B.clone(source);delete s.revision;delete s.updatedAt;if(s.settings){delete s.settings.cloudApi;delete s.settings.cloudOrganization;}return s}
function same(a,b){return JSON.stringify(a)===JSON.stringify(b)}
function mergeSnapshots(base,local,remote,resolveMode=''){const out=B.clone(remote),conflicts=[];for(const k of new Set([...Object.keys(base.settings||{}),...Object.keys(local.settings||{}),...Object.keys(remote.settings||{})])){const b=base.settings?.[k],l=local.settings?.[k],r=remote.settings?.[k];if(k==='cloudApi'||k==='cloudOrganization')continue;const lc=!same(l,b),rc=!same(r,b);if(lc&&rc&&!same(l,r)){if(!resolveMode)conflicts.push(`Préférence « ${k} »`);out.settings[k]=resolveMode==='local'?l:r;}else if(lc)out.settings[k]=l;}for(const table of SYNC_TABLES){const bm=new Map((base[table]||[]).map(x=>[x.id,x])),lm=new Map((local[table]||[]).map(x=>[x.id,x])),rm=new Map((remote[table]||[]).map(x=>[x.id,x])),ids=new Set([...bm.keys(),...lm.keys(),...rm.keys()]),merged=[];for(const id of ids){const b=bm.get(id),l=lm.get(id),r=rm.get(id),lc=!same(l,b),rc=!same(r,b);if(lc&&rc&&!same(l,r)){if(!resolveMode)conflicts.push(`${table} · ${id}`);const value=resolveMode==='local'?l:r;if(value!==undefined)merged.push(value);continue;}const value=lc?l:r;if(value!==undefined)merged.push(value);}out[table]=merged;}const audit=new Map([...(remote.audit||[]),...(local.audit||[])].map(x=>[x.id,x]));out.audit=Array.from(audit.values()).sort((a,b)=>(a.at||'').localeCompare(b.at||'')).slice(-5000);if(conflicts.length)return {conflicts};try{return {snapshot:B.validate(out),conflicts:[]}}catch(e){return {conflicts:[`Données incompatibles : ${e.message}`]}}}
function syncStatus(message){syncMessage=message;const x=$('#cloudSyncStatus');if(x)x.textContent=message;}
function queueCloudSync(delay=1300){if(applyingCloud||!cloudToken||!cloudOrgId()||!navigator.onLine)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>cloudSync(),delay);}
async function cloudSync(){if(syncBusy||applyingCloud||!cloudToken||!cloudOrgId()||!navigator.onLine)return;syncBusy=true;try{const org=cloudOrgId(),path=`/v1/organizations/${encodeURIComponent(org)}/apps/biznako/snapshot`;syncStatus(t('Synchronisation en cours…','Mampifanaraka…'));const d=await cloudRequest(path);let usage=d.usage||null;let local=syncSnapshot(state);let base=await readStore('cloud-base');let remote=d.snapshot?syncSnapshot(d.snapshot):null;if(!base&&remote){const chooseCloud=confirm(t(`Une sauvegarde Cloud existe (révision ${d.revision}). OK : conserver la copie Cloud sur cet appareil. Annuler : choisir explicitement si la copie locale doit remplacer la copie Cloud.`,`Misy tahiry Cloud (dika ${d.revision}). OK: tehirizo eto ny Cloud. Cancel: fidio mazava raha hosoloina amin’ny eo an-toerana ny Cloud.`));if(chooseCloud){applyingCloud=true;const n=B.clone(B.validate(remote));n.settings={...n.settings,cloudApi:state.settings.cloudApi,cloudOrganization:org};await persist(n,t('Première synchronisation AppForge Cloud','Fampifanarahana voalohany AppForge Cloud'));applyingCloud=false;local=syncSnapshot(state);base=remote;}else{if(!confirm(t('Remplacer entièrement la copie Cloud par les données locales de cet appareil ?','Hosoloina tanteraka amin’ny angona eto an-toerana ve ny Cloud?')))return;const saved=await cloudRequest(path,{method:'PUT',body:JSON.stringify({expectedRevision:d.revision,snapshot:local})});await writeAux(local,'cloud-base');usage=saved.usage||usage;syncStatus(t(`Copie locale envoyée · révision Cloud ${saved.revision}.${usage?` Usage synchronisation : ${usage.requests}/${usage.limit}.`:''}`,`Nalefa ny angona eto an-toerana · dika Cloud ${saved.revision}.`));return;}}
 let merged;if(!remote)merged=local;else if(!base)merged=local;else{let m=mergeSnapshots(syncSnapshot(base),local,remote);if(m.conflicts.length){const preferLocal=confirm(t(`Conflit sur ${m.conflicts.length} élément(s) : ${m.conflicts.slice(0,5).join(', ')}. OK conserve les versions de cet appareil pour ces éléments; Annuler conserve les versions Cloud. Les autres changements compatibles seront fusionnés.`,`Fifanoherana amin’ny singa ${m.conflicts.length}: ${m.conflicts.slice(0,5).join(', ')}. OK: tehirizo ny eto an-toerana; Cancel: tehirizo Cloud.`));m=mergeSnapshots(syncSnapshot(base),local,remote,preferLocal?'local':'cloud');}if(m.conflicts.length){syncStatus(t(`Fusion interrompue : ${m.conflicts.join(', ')}. Les données restent intactes.`,`Najanona ny fampifangaroana. Mbola voatahiry ny angona.`));return;}merged=syncSnapshot(m.snapshot);}
 const changed=!remote||!same(merged,remote);let revision=d.revision;if(changed){const saved=await cloudRequest(path,{method:'PUT',body:JSON.stringify({expectedRevision:d.revision,snapshot:merged})});revision=saved.revision;usage=saved.usage||usage;}if(!same(syncSnapshot(state),merged)){applyingCloud=true;const n=B.clone(B.validate(merged));n.settings={...n.settings,cloudApi:state.settings.cloudApi,cloudOrganization:org};await persist(n,t('Synchronisation AppForge Cloud reçue','Voaray ny fampifanarahana AppForge Cloud'));applyingCloud=false;}await writeAux(syncSnapshot(state),'cloud-base');syncStatus(t(`Synchronisé · révision Cloud ${revision} · ${new Date().toLocaleTimeString()}${usage?` · usage ${usage.requests}/${usage.limit}${usage.alert?' · alerte 75 %':''}`:''}` ,`Voarindra · dika Cloud ${revision}${usage?` · usage ${usage.requests}/${usage.limit}`:''}`));
 }catch(err){applyingCloud=false;if(err.status===401){cloudToken='';cloudUser=null;await writeAux(null,'cloud-session');}syncStatus(err.status===401?t('Session expirée : reconnectez-vous dans AppForge Cloud. Les données restent sur cet appareil.','Tapitra ny session: midira indray. Mbola eto an-toerana ny angona.'):err.message.includes('Conflit de synchronisation')?t('Une autre session a enregistré entre-temps. Une nouvelle vérification va reprendre.','Nisy fanovana hafa. Haverina ny fanamarinana.'):t(`Synchronisation suspendue : ${err.message}. Les données restent sur cet appareil.`,`Miato ny sync: ${err.message}. Mbola eto an-toerana ny angona.`));if(err.message.includes('Conflit de synchronisation'))queueCloudSync(1800);}finally{syncBusy=false;}}
async function cloudPull(){syncStatus(t('La synchronisation est automatique. Choisissez une organisation pour démarrer.','Mandeha ho azy ny fampifanarahana. Misafidiana fikambanana.'));await cloudSync()}
async function cloudPush(){syncStatus(t('L’envoi manuel est désactivé pour éviter un écrasement. La synchronisation fusionne les changements compatibles.','Tsy mandeha ny fandefasana tanana mba hisorohana fanoloana. Atambatra ho azy ny fanovana mifanaraka.'));await cloudSync()}
document.addEventListener('submit',async e=>{const form=e.target;if(!['cloudLogin','cloudRegister'].includes(form?.id))return;e.preventDefault();try{if(form.id==='cloudLogin'){await cloudSignin(form);return;}await cloudRegister(form)}catch(err){applyingCloud=false;error(err)}},true);
document.addEventListener('change',e=>{if(e.target?.id==='cloudOrg'&&e.target.value){const n=B.clone(state);n.settings.cloudOrganization=e.target.value;persist(n,t('Organisation Cloud sélectionnée','Voafidy ny fikambanana Cloud')).then(()=>{cloudLoadMembers(e.target.value);queueCloudSync(100)}).catch(error)}},true);
window.addEventListener('online',()=>cloudToken?queueCloudSync(300):restoreCloudSession());document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(cloudToken)queueCloudSync(300);else restoreCloudSession()}});
async function restoreCloudSession(){try{const saved=await readStore('cloud-session');if(!saved?.token||!cloudBase()||!navigator.onLine)return;cloudToken=saved.token;const d=await cloudRequest('/v1/session');cloudUser=d.user;cloudOrganizations=d.organizations||[];queueCloudSync(250)}catch(e){cloudToken='';cloudUser=null;if(e.message.includes('Session expirée'))await writeAux(null,'cloud-session')}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,table=b.dataset.table,id=b.dataset.id;try{
if(a==='nav'){go(b.dataset.view);if(b.dataset.filterStatus){query.status=b.dataset.filterStatus;render();}return;}if(a==='menu'){$('#sidebar').classList.toggle('open');return;}if(a==='close'){close();return;}if(a==='add'){edit(table);return;}if(a==='edit'){edit(table,id);return;}if(a==='duplicate'){edit(table,id,true);return;}if(a==='actions'){actions(table,id);return;}if(a==='document'){documentView(table,id);return;}if(a==='pay'){edit('payments');const f=$('#edit-form');if(f){const r=B.get(state,table,id),type=table==='sales'?'sale':'deal';f.elements.document.value=type+':'+id;f.elements.amount.value=Math.max(0,(type==='sale'?B.total(r):B.commission(r))-B.paid(state,type,id));}return;}
if(a==='delete'){if(confirm(t('Supprimer cet élément ? Les éléments référencés par d’autres documents ne peuvent pas être supprimés.','Hamafa ity singa ity? Tsy azo fafana raha mbola ampiasain’ny taratasy hafa.')))await mutate(table,B.get(state,table,id),'delete');return;}
if(a==='addLine'){$('#lines').insertAdjacentHTML('beforeend',lineEditor({lot:state.lots[0].id,qty:1,price:B.get(state,'products',state.lots[0].product).price}));$('#edit-form').dataset.dirty='true';updateTotals();return;}if(a==='removeLine'){b.closest('.line-editor').remove();$('#edit-form').dataset.dirty='true';updateTotals();return;}
if(a==='theme'){const n=B.clone(state);n.settings.theme=state.settings.theme==='light'?'dark':'light';await persist(n);return;}
if(a==='undo'){if(undo&&confirm(t('Annuler la dernière modification ?','Averina ny fanovana farany?'))){await persist(B.clone(undo),t('Annulation de la dernière modification','Famerenana ny fanovana farany'));undo=null;render();}return;}
if(a==='clearFilters'){query={q:'',activity:'',status:'',from:'',to:'',sort:'date-desc'};page=0;render();return;}
if(a==='saveFilter'){const label=prompt(t('Nom de ce filtre','Anaran’ity sivana ity'));if(label){const n=B.clone(state);n.filters.push({id:B.uid(),name:label.slice(0,60),view,query:B.clone(query)});await persist(n);}return;}
if(a==='loadFilter'){const f=state.filters.find(x=>x.id===id);query={...query,...f.query};page=0;render();return;}if(a==='deleteFilter'){if(confirm(t('Supprimer ce filtre ?','Hamafa ity sivana ity?'))){const n=B.clone(state);n.filters=n.filters.filter(x=>x.id!==id);await persist(n);}return;}
if(a==='prev'){page=Math.max(0,page-1);render();return;}if(a==='next'){page++;render();return;}
if(a==='backup'){await backup();return;}if(a==='csv'){await listCSV();return;}
if(a==='auditCSV'){await download('Biznako_journal.csv',B.csv([['Date','Action','ID'],...state.audit.map(x=>[x.at,x.action,x.record||''])]),'text/csv;charset=utf-8');return;}
if(a==='cashCSV'){const m=B.metrics(state,query);await download('Biznako_flux.csv',B.csv([['Date','Type','Référence','Montant Ar'],...m.payments.map(r=>[r.date,'Encaissement',r.ref,r.amount]),...m.expenses.map(r=>[r.date,'Dépense',r.name,-r.amount])]),'text/csv;charset=utf-8');return;}
if(a==='printDoc'){await print(docHtml);return;}if(a==='printList'){const html=`<h1>${esc(state.settings.name)} · ${t(...menus.find(m=>m[0]===view).slice(2))}</h1><p>${fmt(B.today())} · ${esc(query.q)} · ${fmt(query.from)} → ${fmt(query.to)}</p><table><thead><tr>${listColumns(view).map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${filtered(view).map(r=>`<tr>${rowCells(view,r).map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table>`;docHtml=html;modal(t('Aperçu avant impression','Topimaso alohan’ny fanontana'),html,btn(t('Imprimer / PDF','Hanonta / PDF'),'printDoc','','primary'));return;}
if(a==='printReport'){await print($('.content').innerHTML);return;}
if(a==='guide'){guide();return;}if(a==='start'){const n=B.clone(state);n.settings.onboard=true;await persist(n);close();return;}
if(a==='demo'){if(confirm(t('Charger les exemples en remplaçant les données actuelles ? Exportez une sauvegarde avant de confirmer.','Hampiditra ohatra ka hanolo ny angona ankehitriny? Manaova tahiry alohan’ny hanekena.'))){const n=B.demo();n.settings.lang=state.settings.lang;n.settings.theme=state.settings.theme;await persist(n,'Démonstration chargée');close();go('dashboard');}return;}
if(a==='reset'||a==='resetDemo'){if(confirm(t('Effacer toute la base et repartir vide ? Cette action concerne aussi vos ajouts éventuels.','Hamafa ny tahiry rehetra ka hanomboka foana? Ho voafafa koa izay nampidirinao.'))&&prompt(t('Tapez EFFACER pour confirmer.','Soraty EFFACER hanamafisana.'))==='EFFACER'){const n=B.empty();n.settings={...state.settings,demo:false,onboard:true};await persist(n,'Base réinitialisée');close();go('dashboard');}return;}
if(a==='recover'){const previous=await readStore('previous');if(!previous)throw Error(t('Aucune version précédente disponible.','Tsy misy tahiry teo aloha.'));if(confirm(t('Restaurer la version précédente ?','Hamerina ny tahiry teo aloha?'))){await persist(B.validate(previous),'Version précédente restaurée');toast(t('Version récupérée.','Tafaverina ny tahiry.'));}return;}
if(a==='statusAdd'){modal(t('Nouveau statut','Sata vaovao'),`<form id="status-form" class="stack">${field(t('Libellé','Anarana'),'label','','text','required maxlength="60"')}${select(t('Effet métier','Fiantraikany'),'effect',[{id:'draft',name:t('Brouillon : aucun effet','Drafitra: tsy misy fiantraikany')},{id:'valid',name:t('Validé : stock et calculs actifs','Voamarina: mandeha ny tahiry sy kajy')},{id:'cancel',name:t('Annulé : exclu des calculs','Nofoanana: tsy tafiditra amin’ny kajy')}],'draft')}<button class="primary">${t('Enregistrer','Hitahiry')}</button></form>`);$('#status-form').onsubmit=async e=>{e.preventDefault();try{const n=B.clone(state);n.statuses.push({id:B.uid(),label:e.target.elements.label.value.trim(),effect:e.target.elements.effect.value});await persist(n,'Statut ajouté');close();}catch(err){error(err);}};return;}
if(a==='statusDelete'){if(confirm(t('Supprimer ce statut ?','Hamafa ity sata ity?'))){const n=B.clone(state);n.statuses=n.statuses.filter(s=>s.id!==id);await persist(n,'Statut supprimé');}return;}
if(a==='cloudInfo'){openCloudModal();return;}if(a==='cloudSignout'){try{if(cloudToken)await cloudRequest('/v1/auth/logout',{method:'POST',body:'{}'});}catch{}cloudToken='';cloudOrganizations=[];cloudUser=null;await writeAux(null,'cloud-session');openCloudModal('Déconnecté. La session de cet appareil a été révoquée.');return;}if(a==='cloudSyncNow'){await cloudSync();return;}if(a==='cloudLoadOrgs'){await cloudLoadOrganizations();return;}if(a==='cloudCreateOrg'){await cloudCreateOrganization();return;}if(a==='cloudInvite'){await cloudInvite();return;}if(a==='cloudAcceptInvite'){await cloudAcceptInvite();return;}if(a==='cloudPush'){await cloudPush();return;}if(a==='cloudPull'){await cloudPull();return;}
if(a==='reminder'){const d=new Date();d.setDate(d.getDate()+1);d.setHours(18,0,0,0);await bridge().scheduleReminder({at:d.getTime(),title:'Biznako',body:t('Pensez à enregistrer vos ventes et encaissements.','Aza adino ny mandrakitra ny varotra sy vola voaray.')});toast(t('Rappel demandé pour demain vers 18 h.','Fampahatsiahivana rahampitso amin’ny 18 ora eo ho eo.'));return;}
if(a==='cancelReminder'){await bridge().cancelReminder();toast(t('Rappel annulé.','Nofoanana ny fampahatsiahivana.'));return;}
}catch(err){error(err);}});
document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const focus=$$('#modal button:not([disabled]), #modal input, #modal select, #modal textarea').filter(el=>!el.hidden);const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.bizBack=()=>{if(!$('#modal').hidden){close();return;}if(view!=='dashboard'){go('dashboard');return;}if(confirm(t('Quitter Biznako ? Vos données enregistrées sont conservées.','Hivoaka an’i Biznako? Voatahiry ny angona.')))bridge().exitApp();};
window.addEventListener('unhandledrejection',e=>{e.preventDefault();error(e.reason);});
async function init(){try{await openDB();const saved=await readStore('current');state=saved?B.validate(saved):B.empty();if(!saved)await writeStore(state,0);render();restoreCloudSession();if(!state.settings.onboard)guide();}catch(err){console.error('[Biznako startup]',err.message);$('#app').innerHTML=`<section class="error-screen card"><h1>Biznako</h1><p class="error">${esc(err.message)}</p><p>Impossible d’ouvrir les données. Aucune donnée existante n’a été écrasée. Utilisez un navigateur normal, autorisez le stockage puis réessayez.</p><button onclick="location.reload()">Réessayer / Andramo indray</button><button id="emergency">Exporter les données brutes</button></section>`;$('#emergency').onclick=async()=>{try{const raw=db&&await readStore('current');if(raw)await download('Biznako_recuperation.json',JSON.stringify(raw,null,2));else alert('Aucune donnée accessible.');}catch(e){alert(e.message);}};}}
init();
})();
